import{_ as i,c as n,o as t,a3 as s}from"./chunks/framework.CoV49S2T.js";const c=JSON.parse('{"title":"Fehlerbehebung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/troubleshooting.md","filePath":"de/guide/troubleshooting.md","lastUpdated":1787284674000}'),a={name:"de/guide/troubleshooting.md"};function l(r,e,o,h,d,p){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h1><p>Diese Seite sammelt häufige Probleme mit ClipboxAI unter macOS und deren Lösung.</p><h2 id="die-app-startet-nicht-oder-sturzt-beim-start-ab" tabindex="-1">Die App startet nicht oder stürzt beim Start ab <a class="header-anchor" href="#die-app-startet-nicht-oder-sturzt-beim-start-ab" aria-label="Permalink to &quot;Die App startet nicht oder stürzt beim Start ab&quot;">​</a></h2><ol><li>Stellen Sie sicher, dass Ihre macOS-Version die Mindestanforderung erfüllt (macOS 14 Sonoma+).</li><li>Beenden Sie die App und starten Sie sie neu.</li><li>Starten Sie Ihren Mac neu.</li><li><s>Falls von GitHub Releases heruntergeladen, versuchen Sie den neuesten oder notariellen Build.</s></li><li>Falls die Probleme bestehen bleiben, sammeln Sie Protokolle (unten) und öffnen Sie ein Issue.</li></ol><h2 id="der-zwischenablagen-verlauf-erfasst-keine-kopien" tabindex="-1">Der Zwischenablagen-Verlauf erfasst keine Kopien <a class="header-anchor" href="#der-zwischenablagen-verlauf-erfasst-keine-kopien" aria-label="Permalink to &quot;Der Zwischenablagen-Verlauf erfasst keine Kopien&quot;">​</a></h2><p>Symptome: Neue Kopien erscheinen nicht im Verlaufs-Panel.</p><p>Checkliste:</p><ol><li>Stellen Sie sicher, dass die App läuft und ihr Menüleisten-Symbol sichtbar ist.</li><li>Bestätigen Sie, dass <strong>Clipboard monitoring</strong> unter <strong>Einstellungen → Privacy / General</strong> aktiviert ist.</li><li>Die App benötigt die entsprechende macOS-Berechtigung, um das Pasteboard im Hintergrund zu lesen — siehe <a href="/de/guide/permissions.html">Berechtigungen</a>.</li><li>Einige Apps (Passwort-Manager, sichere Eingabefelder) blockieren den Zwischenablage-Zugriff absichtlich; das ist erwartungsgemäß.</li></ol><h2 id="cloud-ki-aktionen-liefern-kein-ergebnis" tabindex="-1">Cloud-KI-Aktionen liefern kein Ergebnis <a class="header-anchor" href="#cloud-ki-aktionen-liefern-kein-ergebnis" aria-label="Permalink to &quot;Cloud-KI-Aktionen liefern kein Ergebnis&quot;">​</a></h2><p>Symptome: Eine KI-Aktion schlägt fehl, hängt oder zeigt einen Konfigurationsfehler.</p><p>Checkliste:</p><ol><li>Öffnen Sie <strong>Einstellungen → KI</strong> und bestätigen Sie, dass ein Anbieter ausgewählt und ein Schlüssel eingegeben ist.</li><li>Prüfen Sie, dass der Schlüssel für diesen Anbieter gültig ist und Kontingent/Guthaben besitzt.</li><li>Prüfen Sie Ihre Netzwerkverbindung — Cloud-KI benötigt Internetzugriff.</li><li>Bestätigen Sie, dass der ausgewählte Modellname für den Anbieter korrekt ist.</li><li>Falls das Konfigurations-Banner weiterhin im KI-Werkzeug-Fenster erscheint, ist der Schlüssel nicht im Keychain gespeichert; geben Sie ihn erneut ein.</li></ol><h2 id="marketplace-installation-fugt-die-aktion-nicht-hinzu" tabindex="-1">Marketplace-Installation fügt die Aktion nicht hinzu <a class="header-anchor" href="#marketplace-installation-fugt-die-aktion-nicht-hinzu" aria-label="Permalink to &quot;Marketplace-Installation fügt die Aktion nicht hinzu&quot;">​</a></h2><p>Symptome: Ein Klick auf <strong>Install</strong> bewirkt nichts, oder die App öffnet nicht.</p><p>Checkliste:</p><ol><li>Der Deep-Link <code>clipboxai://install?action=&lt;id&gt;</code> muss von der installierten App verarbeitet werden — stellen Sie sicher, dass ClipboxAI installiert ist und läuft.</li><li>Falls Ihr Browser den Deep-Link blockiert, kopieren Sie ihn und öffnen Sie ihn manuell, oder installieren Sie über den Reiter <strong>Marketplace</strong> innerhalb der App.</li><li>Prüfen Sie, dass die Aktions-ID weiterhin im Marketplace veröffentlicht ist.</li></ol><h2 id="zurucksetzen-der-app" tabindex="-1">Zurücksetzen der App <a class="header-anchor" href="#zurucksetzen-der-app" aria-label="Permalink to &quot;Zurücksetzen der App&quot;">​</a></h2><p>Um Einstellungen zurückzusetzen und lokale Daten zu löschen:</p><ol><li>Beenden Sie ClipboxAI.</li><li>Entfernen Sie den Container (dies löscht Verlauf und Einstellungen):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><ol start="3"><li>Öffnen Sie die App erneut und konfigurieren Sie sie neu. API-Schlüssel im Keychain müssen ggf. separat in der <strong>Keychain Access</strong> entfernt werden.</li></ol><h2 id="so-sammeln-sie-debug-protokolle" tabindex="-1">So sammeln Sie Debug-Protokolle <a class="header-anchor" href="#so-sammeln-sie-debug-protokolle" aria-label="Permalink to &quot;So sammeln Sie Debug-Protokolle&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy logs to Desktop for sharing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard/Data/Library/Logs/Clipboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">AI/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>Öffnen Sie anschließend ein Issue auf <a href="https://github.com/clipboxAI" target="_blank" rel="noreferrer">GitHub</a> und hängen Sie die Protokolle an.</p><h2 id="ein-issue-melden" tabindex="-1">Ein Issue melden <a class="header-anchor" href="#ein-issue-melden" aria-label="Permalink to &quot;Ein Issue melden&quot;">​</a></h2><p>Wenn Sie ein Issue öffnen, geben Sie an:</p><ul><li>macOS-Version (Apple-Menü → Über diesen Mac)</li><li>ClipboxAI-Version (App-Menü → Über)</li><li>Schritte zur Reproduktion</li><li>Protokolle (siehe oben)</li></ul><p>Das hilft den Maintainern, das Problem schneller zu identifizieren und zu beheben.</p>`,28)])])}const g=i(a,[["render",l]]);export{c as __pageData,g as default};
